import type { AuthStrategy, AuthStrategyHost, AuthType } from '../../types';
import { createCaptchaStrategy } from '../createCaptchaStrategy';
import { createMobileStrategy } from '../createMobileStrategy';
import { createVkIdStrategy } from '../createVkIdStrategy';

/** Стратегия авторизации по способу, выбранному проектом */
export const createAuthStrategy = (authType: AuthType, host: AuthStrategyHost): AuthStrategy => {
  switch (authType) {
    case 'vkid':
      return createVkIdStrategy(host);
    case 'mobile':
      return createMobileStrategy(host);
    default:
      return createCaptchaStrategy(host);
  }
};
