import type { FunctionalComponent as FC } from "preact";
import { useEffect, useState } from "preact/hooks";

import { AdaptivityProvider, AppRoot, ConfigProvider } from "@vkontakte/vkui";

import type { TokenManagerData } from "../../types/token-manager";
import type { getThemeConfig } from "../../utils";
import { tokenManager } from "../../utils";

import { WebSocketWrapper } from "../WebSocketWrapper";
import { Widget } from "../Widget";

interface Props {
  themeConfig: ReturnType<typeof getThemeConfig>;
  /** Контейнер порталов VKUI внутри Shadow Root. Без него всплывающие элементы рендерятся в document.body */
  portalRoot?: HTMLElement;
}

/** Сессия виджета: пересоздаётся при logout вместе с WidgetProvider */
export const WidgetSession: FC<Props> = ({ themeConfig, portalRoot }) => {
  const [token, setToken] = useState(tokenManager.getToken());

  useEffect(() => {
    const callback = (data?: TokenManagerData) => {
      if (data?.token) {
        setToken(data.token);
      }
    };

    tokenManager.subscribe(callback);

    return () => tokenManager.unsubscribe(callback);
  }, []);

  return (
    <WebSocketWrapper token={token}>
      <ConfigProvider colorScheme="light" tokensClassNames={themeConfig}>
        <AdaptivityProvider>
          <AppRoot
            mode="embedded"
            portalRoot={portalRoot}
            disableParentTransformForPositionFixedElements
          >
            <Widget />
          </AppRoot>
        </AdaptivityProvider>
      </ConfigProvider>
    </WebSocketWrapper>
  );
};
