import { createIsland } from 'preact-island';
import type { Island } from 'preact-island';

import { WidgetWrapper } from '../../components/WidgetWrapper';
import type { WidgetTheme } from '../../types/theme';

import { authService, mobileAuthBridge } from '../../auth';
import type { AuthTokenProvider } from '../../auth/types';
import { prepareWidgetShadowRoot } from '../shadowDom';
import { websocketConnectionManager } from '../websocketConnectionManager';

interface WidgetWrapperProps {
  widgetTitle: string;
  companyLogoSrc?: string;
  widgetUuid?: string;
  widgetTheme?: WidgetTheme;
  entryPointGateway?: string;
  requirePhone?: boolean;
  panelOffsetTop?: number;
  hideTriggerButton?: boolean;
  widgetLocale?: string;
  authType?: string;
  /** Контейнер порталов VKUI внутри Shadow Root, создаётся при монтировании */
  portalRoot?: HTMLElement;
}

// Todo добавить отписывание от событий
class WidgetManager {
  // CustomEvent для document.addEventListener
  static readonly DISPATCH_OPEN = 'vks-widget-open';
  static readonly DISPATCH_CLOSE = 'vks-widget-close';
  static readonly DISPATCH_NEW_MESSAGE = 'vks-widget-new-message';

  private islandInstance: Island<WidgetWrapperProps> | null = null;
  private isMounted: boolean = false;
  private currentUrl: string = window.location.origin;
  private currentPathname: string = window.location.pathname;
  private selector: string = '[data-island="widget-chat"]';
  private widgetVisibilityCallback: ((isVisible: boolean) => void) | null | undefined = null;
  private externalVisibilityCallback: ((isVisible: boolean) => void) | null | undefined = null;
  private lastNotifiedVisible: boolean | null = null;
  private hasNewMessageState = false;
  private externalNewMessageCallback: ((hasNewMessage: boolean) => void) | null | undefined = null;

  constructor() {
    this.initHistoryListener();
    this.initDataAttributeListener();
  }

  init(): void {
    this.checkAndMountWidget();
  }

  setVisibilityCallback(callback: ((isVisible: boolean) => void) | undefined): void {
    this.externalVisibilityCallback = callback;
  }

  setInternalVisibilityCallback(callback: ((isVisible: boolean) => void) | undefined): void {
    this.widgetVisibilityCallback = callback;
  }

  notifyVisibilityChange(isVisible: boolean): void {
    if (this.externalVisibilityCallback) {
      this.externalVisibilityCallback(isVisible);
    }
    if (this.lastNotifiedVisible !== isVisible) {
      this.lastNotifiedVisible = isVisible;
      const eventName = isVisible ? WidgetManager.DISPATCH_OPEN : WidgetManager.DISPATCH_CLOSE;
      document.dispatchEvent(new CustomEvent(eventName, { bubbles: true }));
    }
  }

  /** Есть ли непрочитанное входящее сообщение */
  hasNewMessage(): boolean {
    return this.hasNewMessageState;
  }

  /** Callback на появление и сброс непрочитанного сообщения */
  setNewMessageCallback(callback: ((hasNewMessage: boolean) => void) | undefined): void {
    this.externalNewMessageCallback = callback;
  }

  notifyNewMessageChange(hasNewMessage: boolean): void {
    if (this.hasNewMessageState === hasNewMessage) {
      return;
    }

    this.hasNewMessageState = hasNewMessage;
    this.externalNewMessageCallback?.(hasNewMessage);
    document.dispatchEvent(
      new CustomEvent(WidgetManager.DISPATCH_NEW_MESSAGE, { bubbles: true, detail: { hasNewMessage } })
    );
  }

  openWidget(): void {
    if (this.widgetVisibilityCallback) {
      this.widgetVisibilityCallback(true);
    }
    this.notifyVisibilityChange(true);
  }

  closeWidget(): void {
    if (this.widgetVisibilityCallback) {
      this.widgetVisibilityCallback(false);
    }
    this.notifyVisibilityChange(false);
  }

  /**
   * Провайдер токена внешнего проекта для data-auth-type="mobile".
   * Виджет вызывает его при старте и перед истечением своего JWT, токен проекта не хранится
   */
  setAuthTokenProvider(provider: AuthTokenProvider | null | undefined): void {
    mobileAuthBridge.setProvider(provider);
  }

  /** Выход пользователя: очищает токены и данные виджета, закрывает соединение и переписку */
  logout(): void {
    authService.logout();
  }

  private initDataAttributeListener(): void {
    // Обработчик кликов для элементов с data-vks-open-widget
    document.addEventListener('click', (event) => {
      const target = event.target as HTMLElement;
      const openWidgetElement = target.closest('[data-vks-open-widget]');

      if (openWidgetElement) {
        event.preventDefault();
        this.openWidget();
      }
    });
  }

  private checkAndMountWidget(): void {
    const containers = document.querySelectorAll<HTMLElement>(this.selector);

    if (containers.length > 0 && !this.isMounted) {
      // Shadow Root изолирует стили виджета (VKUI + свои) от стилей хост-приложения.
      // preact-island видит shadowRoot на элементе и рендерит виджет внутрь него.
      const shadowRoots = new Map<HTMLElement, HTMLDivElement>();

      containers.forEach((container) => {
        const { portalRoot } = prepareWidgetShadowRoot(container);
        shadowRoots.set(container, portalRoot);
      });

      this.islandInstance = createIsland(WidgetWrapper);
      this.islandInstance?.render({
        selector: this.selector,
        initialProps: {
          // preact-island рендерит все элементы, найденные по селектору — обычно он один,
          // поэтому отдаём portalRoot первого; data-атрибуты хоста мерджатся поверх initialProps
          portalRoot: shadowRoots.values().next().value,
        },
      });
      this.isMounted = true;
    }
  }

  private unmountWidget(): void {
    if (this.islandInstance && this.isMounted) {
      // Закрываем все WebSocket соединения перед размонтированием
      void websocketConnectionManager.closeAllConnections();

      this.islandInstance.destroy();
      this.isMounted = false;
    }
  }

  private initHistoryListener(): void {
    const originalPushState = history.pushState;
    const originalReplaceState = history.replaceState;

    history.pushState = (...args) => {
      originalPushState.apply(history, args);
      this.handleRouteChange();
    };

    history.replaceState = (...args) => {
      originalReplaceState.apply(history, args);
      this.handleRouteChange();
    };

    window.addEventListener('popstate', () => {
      this.handleRouteChange();
    });
  }

  private handleRouteChange(): void {
    const newUrl = window.location.origin;
    const newPathname = window.location.pathname;

    if (newPathname !== this.currentPathname) {
      this.closeWidget();
    }

    if (newUrl !== this.currentUrl) {
      this.currentUrl = newUrl;
      this.unmountWidget();
    }
  }
}

export const widgetManager = new WidgetManager();
