import { NotificationTextLanguages } from './constants.js';
import { VERSION } from '../common/constants.js';
import { hasAllowedAppSettingsParams, makeAppSettingsString, makeParams } from '../common/utils.js';
import { Config } from '../config/config.js';
import { CONNECT_AUTH_RESPONSE_TYPE } from '../connect/utils.js';

const isAutologinRetryAvailable = (hours)=>{
    const autologinLastTry = localStorage.getItem('vkid_auth_by_autologin_timestamp');
    if (!autologinLastTry || isNaN(Number(autologinLastTry))) {
        return true;
    }
    const msHours = hours * 60 * 60 * 1000;
    return Number(autologinLastTry) + msHours <= new Date().getTime();
};
const setAutologinTimestamp = ()=>{
    localStorage.setItem('vkid_auth_by_autologin_timestamp', new Date().getTime().toString());
};
function makeAutologinUrl(params) {
    return Config.fetchDomain().then(()=>{
        const { appId, loginDomain, appSettings, _debug, _localhost } = Config.get();
        const urlParamsObj = {
            act: 'autologin',
            app_id: appId,
            response_type: CONNECT_AUTH_RESPONSE_TYPE,
            v: VERSION,
            debug: _debug ? 1 : null,
            localhost: _localhost ? 1 : null,
            ...params
        };
        if (appSettings && hasAllowedAppSettingsParams(appSettings)) {
            urlParamsObj.app_settings = makeAppSettingsString(appSettings);
        }
        const urlParams = makeParams(urlParamsObj);
        return Promise.resolve(`https://${loginDomain}/?${urlParams}`);
    });
}
const notificationText = (langId)=>{
    return NotificationTextLanguages[langId] ? NotificationTextLanguages[langId] : NotificationTextLanguages[0];
};

export { isAutologinRetryAvailable, makeAutologinUrl, notificationText, setAutologinTimestamp };
