import { Icon24Send, Icon24Smile, Icon24SmileOutline } from '@vkontakte/icons';
import { Button, Flex } from '@vkontakte/vkui';
import baseTheme from '@vkontakte/vkui-tokens/themes/vkBase';

import { useWidget } from '../../context/WidgetContext';

import styles from './styles.module.css';

interface Props {
  showSendButton: boolean;
  onToggleEmojiPanel: () => void;
}

export const WidgetEditorRightPanel = ({ showSendButton, onToggleEmojiPanel }: Props) => {
  const { widgetTheme } = useWidget();

  const emojiIcon =
    widgetTheme === 'dso' ? (
      <Icon24Smile className={styles.dsoIcon} width={32} height={32} fill="currentColor" />
    ) : (
      <Icon24SmileOutline fill={baseTheme.colorIconSecondary.normal} />
    );

  return (
    <Flex noWrap>
      <Button type="button" mode="tertiary" data-emoji-panel-trigger onClick={onToggleEmojiPanel} before={emojiIcon} />

      {showSendButton && (
        <Button mode="tertiary" type="submit" before={<Icon24Send className={styles.sendButtonIcon} />} />
      )}
    </Flex>
  );
};
