import type { AuthType } from '../auth/types';

/** Способ авторизации без data-auth-type: капча, чтобы не сломать уже встроенные виджеты */
export const DEFAULT_AUTH_TYPE: AuthType = 'captcha';

/** Как часто authService проверяет срок жизни токена */
export const TOKEN_CHECK_MS = 5000;

/** Сколько vkid ждёт обмена payload VK ID на JWT, прежде чем показать капчу */
export const VKID_PENDING_TIMEOUT_MS = 10_000;

/** Сколько mobile ждёт, пока внешний проект передаст провайдер токена */
export const PROVIDER_WAIT_MS = 10_000;

/** Сколько mobile ждёт ответа провайдера */
export const PROVIDER_CALL_TIMEOUT_MS = 10_000;

/** Не больше PROVIDER_CALLS_LIMIT вызовов провайдера за PROVIDER_CALLS_WINDOW_MS, чтобы не нагружать приложение */
export const PROVIDER_CALLS_LIMIT = 5;
export const PROVIDER_CALLS_WINDOW_MS = 60_000;

/** Паузы между повторами обмена при временных ошибках (5xx, сеть, провайдер) */
export const RETRY_DELAYS_MS = [1_000, 3_000, 10_000];

/** Разброс пауз ±30%, чтобы виджеты не повторяли запросы одновременно, если бэкенд упал */
export const RETRY_JITTER = 0.3;

/** Максимальный Retry-After при 429, который готовы подождать для одного повтора */
export const MAX_RETRY_AFTER_SEC = 60;

/** Не чаще одного нового цикла авторизации по действию пользователя после неудачи */
export const USER_RETRY_COOLDOWN_MS = 30_000;

/** За сколько секунд до истечения JWT mobile получает новый */
export const REFRESH_BEFORE_EXPIRE_SEC = 60;
