/** Через сколько секунд бэкенд разрешает повторить запрос (заголовок Retry-After при 429) */
export const getRetryAfterSec = (response: Response) => {
  const value = response.headers.get('Retry-After');

  if (!value) {
    return undefined;
  }

  const seconds = Number(value);

  return Number.isFinite(seconds) && seconds >= 0 ? seconds : undefined;
};
