import { tokenManager } from '../../../utils/tokenManager';

import type { AuthStrategy, AuthStrategyHost } from '../../types';

/**
 * Авторизация по капче: капча показывается при первом действии пользователя.
 * Сама капча и обмен её токена на JWT — в компоненте Captcha
 */
export const createCaptchaStrategy = (host: AuthStrategyHost): AuthStrategy => ({
  // Токен мог истечь, пока страница была закрыта. Переносим его в oldToken:
  // Captcha отправит его вместе с капчей, и бэкенд оставит пользователю его переписку
  init() {
    tokenManager.expireToken();
  },

  requestAuth() {
    if (host.getStatus() !== 'authorized') {
      host.setStatus('challenge');
    }
  },

  // Токен истёк во время работы: так же переносим в oldToken. Статус станет unauthorized,
  // и следующее действие пользователя откроет капчу
  onTick() {
    tokenManager.expireToken();
  },
});
