.rateAnswer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  background-color: var(--rating-bg, var(--vkui--color_background_tertiary));
  border-radius: 12px;
  padding: 8px;
}

.emptyIcons svg {
  display: inline-block;
  fill: var(--rating-star-empty-color, #b8c1cc);
}

.filledIcons svg {
  display: inline-block;
  fill: var(--rating-star-fill-color);
}
