/* eslint-disable no-console */
import { getTracerModules } from '@apptracer/sdk/lite';
import { jwtDecode } from 'jwt-decode';

import type { TokenManagerData } from '../../types/token-manager';

import { packageName } from '../../../config';
import {
  HAS_MAX_USER_PHONE,
  HAS_NEW_MESSAGE,
  HAS_WIDGET_HISTORY,
  LAST_SEEN_MESSAGE_ID,
  OLD_TOKEN_KEY,
  TOKEN_KEY,
  VKID_AUTOLOGIN_KEY,
} from '../../constants/localStorage';
import { storageManager } from '../storageManager';

type ObserverFunction = (data?: TokenManagerData) => void;

class TokenManager {
  private token: string | null;
  private oldToken: string | null;
  private observers: ObserverFunction[];
  private tracerError = getTracerModules(packageName).error;

  constructor() {
    this.observers = [];
    // Инициализируем токены из стораджа с учётом того, что он может быть недоступен
    try {
      this.token = storageManager?.getItem(TOKEN_KEY) || null;
      this.oldToken = storageManager?.getItem(OLD_TOKEN_KEY) || null;
    } catch (error) {
      this.tracerError?.error('Ошибка получения токенов из хранилища');
      console.error('Error initializing tokens from storage:', error);
      this.token = null;
      this.oldToken = null;
    }
  }

  subscribe(func: ObserverFunction) {
    this.observers.push(func);
  }

  unsubscribe(func: ObserverFunction) {
    this.observers = this.observers.filter((observer) => observer !== func);
  }

  notify(data?: TokenManagerData) {
    this.observers.forEach((observer) => observer(data));
  }

  getToken() {
    return this.token;
  }

  getOldToken() {
    return this.oldToken;
  }

  setOldToken(token: string) {
    this.oldToken = token;
    try {
      storageManager?.setItem(OLD_TOKEN_KEY, token);
    } catch (_) {
      this.tracerError?.error('Ошибка получения старого токена из хранилища');
    }
  }

  getIsTokenExpired() {
    if (this.token) {
      const { exp } = jwtDecode(this.token);
      const currentTime = Math.floor(Date.now() / 1000);

      if (exp) {
        return exp < currentTime;
      }
    }

    return true;
  }

  /** Сколько секунд осталось жить токену. null, если токена нет или в нём нет exp */
  getTokenExpiresIn(): number | null {
    if (!this.token) return null;

    try {
      const { exp } = jwtDecode(this.token);
      return exp ? exp - Math.floor(Date.now() / 1000) : null;
    } catch (_) {
      return null;
    }
  }

  /**
   * Извлекает userUuid из JWT payload (поле sub).
   * Единственный источник userUuid — текущий токен.
   */
  getUserUuid(): string | null {
    if (!this.token) return null;

    try {
      const decoded = jwtDecode<Record<string, unknown>>(this.token);
      return (decoded.sub as string) || null;
    } catch {
      return null;
    }
  }

  setAuthData(data: TokenManagerData) {
    const { token, userUuid } = data;

    if (token && userUuid) {
      this.token = token;

      try {
        storageManager?.setItem(TOKEN_KEY, token);
      } catch (_) {
        this.tracerError?.error('Ощибка сохранения данных авторизации в хранилище', {
          keys: {
            userUuid,
          },
        });
      }

      this.notify(data);
    }
  }

  removeAuthData() {
    try {
      storageManager?.removeItem(TOKEN_KEY);
      storageManager?.removeItem(HAS_MAX_USER_PHONE);
    } catch (_) {
      this.tracerError?.error('Ошибка удаления данных авторизации из хранилища', {
        keys: {
          hasMaxUserPhone: HAS_MAX_USER_PHONE,
        },
      });
    }

    this.token = null;

    this.notify();
  }

  /** Очистка ключей/токенов при 500 от /validate */
  clearAllAuthAndKeys() {
    try {
      storageManager?.removeItem(TOKEN_KEY);
      storageManager?.removeItem(OLD_TOKEN_KEY);
      storageManager?.removeItem(HAS_MAX_USER_PHONE);
    } catch (_) {
      this.tracerError?.error('Ошибка удаления данных авторизации и ключей из хранилища', {
        keys: {
          hasMaxUserPhone: HAS_MAX_USER_PHONE,
        },
      });
    }

    this.token = null;
    this.oldToken = null;

    this.notify();
  }

  /**
   * Переносит просроченный токен в oldToken и удаляет текущий.
   * oldToken нужен капче, чтобы бэкенд сохранил пользователя.
   * Возвращает true, если токен действительно был просрочен
   */
  expireToken(): boolean {
    const token = this.getToken();

    if (token && this.getIsTokenExpired()) {
      this.setOldToken(token);
      this.removeAuthData();
      return true;
    }

    return false;
  }

  /** Полная очистка данных пользователя при logout */
  logout() {
    try {
      storageManager?.removeItem(HAS_WIDGET_HISTORY);
      storageManager?.removeItem(HAS_NEW_MESSAGE);
      storageManager?.removeItem(LAST_SEEN_MESSAGE_ID);
      storageManager?.removeItem(VKID_AUTOLOGIN_KEY);
    } catch (_) {
      this.tracerError?.error('Ошибка удаления данных виджета из хранилища');
    }

    this.clearAllAuthAndKeys();
  }
}

export const tokenManager = new TokenManager();
