import type { TokenManagerData } from '../types/token-manager';

/** Способ авторизации, который выбирает проект через data-auth-type */
const AUTH_TYPES = ['captcha', 'vkid', 'mobile'] as const;

export type AuthType = (typeof AUTH_TYPES)[number];

export const isAuthType = (value: unknown): value is AuthType =>
  typeof value === 'string' && (AUTH_TYPES as readonly string[]).includes(value);

/**
 * Статус авторизации виджета
 * - unauthorized — токена нет, авторизация запустится по действию пользователя
 * - pending — идёт авторизация без участия пользователя (VK ID, внешний токен)
 * - challenge — показана капча
 * - authorized — есть живой токен
 * - error — внешняя авторизация не удалась
 */
export type AuthStatus = 'unauthorized' | 'pending' | 'challenge' | 'authorized' | 'error';

/** Коды ошибок внешней авторизации, пишутся в трейсер */
export type AuthErrorCode =
  'NO_TOKEN' | 'PROVIDER_ERROR' | 'INVALID_TOKEN' | 'FORBIDDEN' | 'RATE_LIMIT' | 'SERVER_ERROR' | 'NETWORK_ERROR';

export interface AuthError {
  code: AuthErrorCode;
  /** HTTP-статус ответа нашего бэкенда, если он был */
  status?: number;
  /** Есть ли смысл повторять запрос с тем же токеном */
  retryable: boolean;
  /** Через сколько секунд бэкенд разрешает повторить запрос (заголовок Retry-After при 429) */
  retryAfterSec?: number;
  /** Код ошибки из тела ответа бэкенда, если он его прислал */
  backendCode?: string;
}

export interface AuthState {
  authType: AuthType;
  status: AuthStatus;
  error: AuthError | null;
  /** Меняется при logout, чтобы пересоздать сессию виджета */
  sessionKey: number;
}

/** Функция внешнего проекта, которая отдаёт его access token */
export type AuthTokenProvider = () => string | null | undefined | Promise<string | null | undefined>;

/** Результат запроса токена у провайдера внешнего проекта */
export type AccessTokenResult = { accessToken: string } | { error: AuthError };

/** Результат обмена токена проекта на JWT виджета */
export type MobileAuthResult = ({ ok: true } & TokenManagerData) | { ok: false; error: AuthError };

/** То, что сервис авторизации отдаёт стратегии */
export interface AuthStrategyHost {
  widgetUuid?: string;
  getStatus(): AuthStatus;
  setStatus(status: AuthStatus, error?: AuthError | null): void;
}

export interface AuthStrategy {
  /** Синхронная подготовка до первого рендера виджета */
  prepare?(): void;
  /** Запуск авторизации при монтировании виджета */
  init(): void;
  /** Пользователю нужно действие, а токена нет */
  requestAuth(): void;
  /** Периодическая проверка токена, раз в TOKEN_CHECK_MS */
  onTick(): void;
  /** Остановка таймеров и незавершённых запросов */
  dispose?(): void;
}
