import type { FunctionalComponent as FC } from 'preact';

import { Icon28Messages, Icon56CommentsOutline } from '@vkontakte/icons';
import { Placeholder } from '@vkontakte/vkui';

import { useWidget } from '../../context/WidgetContext';

import { IconCircle } from '../IconCircle';

import styles from './styles.module.css';

interface Props {
  className?: string;
}

export const EmptyWidgetContent: FC<Props> = ({ className }) => {
  const { localeMessages, widgetTheme } = useWidget();

  const icon =
    widgetTheme === 'dso' ? (
      <IconCircle size={64}>
        <Icon28Messages />
      </IconCircle>
    ) : (
      <Icon56CommentsOutline />
    );

  return (
    <Placeholder
      className={className}
      icon={icon}
      title={<span className={styles.title}>{localeMessages.chat.startChatTitle}</span>}
      stretched
    >
      <span className={styles.description}>{localeMessages.chat.startChatDescription}</span>
    </Placeholder>
  );
};
