import type { TokenManagerData } from '../../types/token-manager';
import { tokenManager } from '../../utils/tokenManager';

import { DEFAULT_AUTH_TYPE, TOKEN_CHECK_MS } from '../../constants/auth';
import { createAuthStrategy } from '../strategies';
import type { AuthError, AuthState, AuthStatus, AuthStrategy, AuthType } from '../types';

interface ConfigureParams {
  authType: AuthType;
  widgetUuid?: string;
}

/**
 * Единая точка авторизации виджета.
 * Хранит статус, выбирает стратегию по authType и следит за сроком жизни токена
 */
class AuthService {
  private state: AuthState = {
    authType: DEFAULT_AUTH_TYPE,
    status: 'unauthorized',
    error: null,
    sessionKey: 0,
  };
  private listeners = new Set<() => void>();
  private strategy: AuthStrategy | null = null;
  private widgetUuid?: string;
  private configKey: string | null = null;
  private isStarted = false;
  private tickTimerId: ReturnType<typeof setInterval> | undefined;

  constructor() {
    tokenManager.subscribe(this.handleTokenChange);
  }

  /**
   * Выбор стратегии. Вызывается синхронно до первого рендера, повторный вызов с теми же параметрами ничего не делает.
   * Запуск стратегии — только через start() из эффекта виджета
   */
  configure({ authType, widgetUuid }: ConfigureParams) {
    const configKey = `${authType}|${widgetUuid ?? ''}`;

    if (this.configKey === configKey) {
      return;
    }

    this.stop();
    this.configKey = configKey;
    this.widgetUuid = widgetUuid;
    this.strategy = createAuthStrategy(authType, this.createHost());
    this.strategy.prepare?.();

    this.setState({
      authType,
      status: tokenManager.getIsTokenExpired() ? 'unauthorized' : 'authorized',
      error: null,
    });
  }

  /** Запуск авторизации при монтировании виджета. Возвращает функцию остановки */
  start = () => {
    if (!this.isStarted && this.strategy) {
      this.isStarted = true;
      this.strategy.init();
      this.tickTimerId = setInterval(() => this.strategy?.onTick(), TOKEN_CHECK_MS);
    }

    return this.stop;
  };

  stop = () => {
    clearInterval(this.tickTimerId);
    this.tickTimerId = undefined;
    this.strategy?.dispose?.();
    this.isStarted = false;
  };

  /** Пользователю нужно действие, а токена нет: капча, повторный обмен или ожидание VK ID */
  requestAuth = () => {
    this.strategy?.requestAuth();
  };

  /** Капча пройдена и обменяна на JWT */
  completeChallenge = (data: TokenManagerData) => {
    tokenManager.setAuthData(data);
  };

  /** Полный выход: очищает данные пользователя и пересоздаёт сессию виджета */
  logout = () => {
    const wasStarted = this.isStarted;

    this.stop();
    tokenManager.logout();

    if (this.strategy) {
      this.strategy = createAuthStrategy(this.state.authType, this.createHost());
    }

    this.setState({
      status: 'unauthorized',
      error: null,
      sessionKey: this.state.sessionKey + 1,
    });

    if (wasStarted) {
      this.start();
    }
  };

  getState = () => this.state;

  subscribe = (listener: () => void) => {
    this.listeners.add(listener);

    return () => {
      this.listeners.delete(listener);
    };
  };

  private createHost() {
    return {
      widgetUuid: this.widgetUuid,
      getStatus: () => this.state.status,
      setStatus: (status: AuthStatus, error: AuthError | null = null) => {
        this.setState({ status, error });
      },
    };
  }

  private handleTokenChange = (data?: TokenManagerData) => {
    if (data?.token) {
      this.setState({ status: 'authorized', error: null });
      return;
    }

    // Токен удалён (истёк или очищен). Капчу и заглушку ошибки не трогаем
    if (this.state.status === 'authorized') {
      this.setState({ status: 'unauthorized' });
    }
  };

  private setState(patch: Partial<AuthState>) {
    const next = { ...this.state, ...patch };

    if (
      next.authType === this.state.authType &&
      next.status === this.state.status &&
      next.error === this.state.error &&
      next.sessionKey === this.state.sessionKey
    ) {
      return;
    }

    this.state = next;
    this.listeners.forEach((listener) => listener());
  }
}

export const authService = new AuthService();
