import { Config } from '@vk-ecosystem/sdk';

import { getAutologinRedirect } from '../../../utils/getAutologinRedirect';
import { getVkIdResponse } from '../../../utils/getVkIdResponse';
import { tokenManager } from '../../../utils/tokenManager';

import { widgetVkIdAppKey } from '../../../../config';
import { VKID_PENDING_TIMEOUT_MS } from '../../../constants/auth';
import type { AuthStrategy, AuthStrategyHost } from '../../types';

/**
 * Авторизация через silent autologin VK ID при загрузке страницы.
 * Если VK ID не вернул токен, по действию пользователя показывается капча
 */
export const createVkIdStrategy = (host: AuthStrategyHost): AuthStrategy => {
  let isAuthRequested = false;
  let pendingTimerId: ReturnType<typeof setTimeout> | undefined;

  // Обмен закончился: если токен не получили, дальше работаем как капча
  const finishPending = () => {
    clearTimeout(pendingTimerId);
    pendingTimerId = undefined;

    if (host.getStatus() === 'pending') {
      host.setStatus(isAuthRequested ? 'challenge' : 'unauthorized');
    }

    isAuthRequested = false;
  };

  const runAutologin = () => {
    if (host.widgetUuid) {
      getAutologinRedirect(host.widgetUuid, finishPending);
    }
  };

  return {
    init() {
      Config.init({
        appId: Number(widgetVkIdAppKey),
      });

      const hasValidToken = !tokenManager.getIsTokenExpired();

      tokenManager.expireToken();

      // VK ID вернул payload в урле: ждём обмена на JWT, пользователю капчу не показываем
      if (!hasValidToken && host.widgetUuid && getVkIdResponse().payload) {
        host.setStatus('pending');
        pendingTimerId = setTimeout(finishPending, VKID_PENDING_TIMEOUT_MS);
      }

      runAutologin();
    },

    requestAuth() {
      const status = host.getStatus();

      if (status === 'authorized') {
        return;
      }

      if (status === 'pending') {
        // Действие выполнится после обмена, а если он не удастся — покажем капчу
        isAuthRequested = true;
        return;
      }

      host.setStatus('challenge');
    },

    onTick() {
      if (tokenManager.expireToken()) {
        runAutologin();
      }
    },

    dispose() {
      clearTimeout(pendingTimerId);
      pendingTimerId = undefined;
      isAuthRequested = false;
    },
  };
};
