import type { AccessTokenResult, AuthTokenProvider } from '../../auth/types';
import { PROVIDER_CALL_TIMEOUT_MS } from '../../constants/auth';
import { withTimeout } from '../withTimeout';

/**
 * Берёт токен проекта у провайдера. Ошибка или таймаут провайдера — PROVIDER_ERROR (можно повторить),
 * пустой ответ — NO_TOKEN (пользователь не авторизован во внешнем проекте, повторять бессмысленно)
 */
export const requestAccessToken = async (provider: AuthTokenProvider): Promise<AccessTokenResult> => {
  try {
    const accessToken = await withTimeout(provider, PROVIDER_CALL_TIMEOUT_MS);

    if (typeof accessToken !== 'string' || accessToken === '') {
      return { error: { code: 'NO_TOKEN', retryable: false } };
    }

    return { accessToken };
  } catch (_) {
    return { error: { code: 'PROVIDER_ERROR', retryable: true } };
  }
};
