import type { FunctionalComponent as FC } from "preact";
import { useEffect, useMemo } from "preact/hooks";

import { PhoneProvider } from "../../context/PhoneContext";
import { WidgetProvider } from "../../context/WidgetContext";
import { useAuth } from "../../hooks/useAuth";
import { useWidgetParams } from "../../hooks/useWidgetParams";
import type { WidgetTheme } from "../../types/theme";
import { getThemeConfig } from "../../utils";
import "@vkontakte/vkui/dist/components.css";

import { authService } from "../../auth";
import { WidgetSession } from "./WidgetSession";

import "./fonts.css";
import "./themes.css";
import "@vkontakte/vkui-tokens/themes/vkBase/cssVars/declarations/onlyVariables.css";

interface Props {
  widgetTitle: string;
  companyLogoSrc?: string;
  widgetUuid?: string;
  widgetTheme?: WidgetTheme;
  entryPointGateway?: string;
  requirePhone?: boolean;
  panelOffsetTop?: number;
  hideTriggerButton?: boolean;
  widgetLocale?: string;
  authType?: string;
  /** Контейнер для порталов VKUI внутри Shadow Root (embed-сборка). Без него порталы уходят в document.body */
  portalRoot?: HTMLElement;
}

export const WidgetWrapper: FC<Props> = ({
  widgetTitle,
  companyLogoSrc,
  widgetUuid,
  entryPointGateway,
  requirePhone,
  widgetTheme = "default",
  panelOffsetTop = 0,
  hideTriggerButton,
  widgetLocale,
  authType,
  portalRoot,
}) => {
  const widgetParams = useWidgetParams({
    widgetTitle,
    companyLogoSrc,
    widgetUuid,
    widgetTheme,
    entryPointGateway,
    requirePhone,
    panelOffsetTop,
    hideTriggerButton,
    widgetLocale,
    authType,
  });

  const {
    widgetUuid: widgetUuidParam,
    widgetTheme: widgetThemeParam,
    panelOffsetTop: panelOffsetTopParam,
    authType: authTypeParam,
  } = widgetParams;

  // Стратегию типа авторизации выбираем до первого рендера: внешняя авторизация должна сбросить сохранённый токен до подключения сокета
  useMemo(() => {
    authService.configure({ authType: authTypeParam, widgetUuid: widgetUuidParam });
  }, [authTypeParam, widgetUuidParam]);

  useEffect(() => authService.start(), [authTypeParam, widgetUuidParam]);

  // При logout пересоздаём сессию: сбрасываются переписка, сокет и состояние виджета
  const { sessionKey } = useAuth();

  const themeConfig = getThemeConfig(widgetThemeParam);

  useEffect(() => {
    document.documentElement.style.setProperty(
      "--vks-support-widget-panel-offset-top",
      panelOffsetTopParam + "px",
    );
  }, [panelOffsetTopParam]);

  return (
    <WidgetProvider key={sessionKey} {...widgetParams}>
      <PhoneProvider>
        <WidgetSession themeConfig={themeConfig} portalRoot={portalRoot} />
      </PhoneProvider>
    </WidgetProvider>
  );
};
