import { useEffect, useState } from 'preact/hooks';

import { authService } from '../auth';

/** Состояние авторизации для компонентов */
export const useAuth = () => {
  const [state, setState] = useState(authService.getState);

  useEffect(() => {
    const unsubscribe = authService.subscribe(() => setState(authService.getState()));

    // Статус мог измениться между рендером и подпиской
    setState(authService.getState());

    return unsubscribe;
  }, []);

  return {
    ...state,
    isAuthorized: state.status === 'authorized',
    requestAuth: authService.requestAuth,
  };
};
