import { BRIDGE_MESSAGE_TYPE_SDK } from './constants.js';
import { bridgeConfigValidator, bridgeHandlerValidator, messageDataRequirementValidator, messageEventValidator } from './validators.js';

class Bridge {
    handler = ()=>({});
    config;
    constructor(config){
        const validationResult = bridgeConfigValidator.validate(config);
        !validationResult.isValid() && console.error(validationResult.error());
        this.config = config;
        window.addEventListener('message', this.handleMessage);
    }
    destroy = ()=>{
        /* Clear references for memory */ // @ts-ignore-next-line Удаление происходит при десктруктуризации бриджа, поэтому это безопасно.
        delete this.config;
        window.removeEventListener('message', this.handleMessage);
    };
    onMessage = (handler)=>{
        const validationResult = bridgeHandlerValidator.validate({
            handler
        });
        !validationResult.isValid() && console.error(validationResult.error());
        this.handler = handler;
    };
    sendMessage = (message)=>{
        const validationResult = messageDataRequirementValidator.validate(message);
        !validationResult.isValid() && console.error(validationResult.error());
        this.config.iframe.contentWindow?.postMessage({
            type: BRIDGE_MESSAGE_TYPE_SDK,
            ...message
        }, this.config.origin);
    };
    handleMessage = (event)=>{
        const validationResult = messageEventValidator.validate({
            event
        });
        !validationResult.isValid() && console.error(validationResult.error());
        if (!this.config.origin || event.origin !== this.config.origin) {
            return;
        }
        if (event.source !== this.config.iframe.contentWindow) {
            return;
        }
        if (!(event.data && event.data.type === BRIDGE_MESSAGE_TYPE_SDK)) {
            return;
        }
        this.handler(event.data);
    };
}

export { Bridge as default };
