import { Spinner } from '@vkontakte/vkui';

import { useWidget } from '../../context/WidgetContext';
import { useAuth } from '../../hooks/useAuth';

import { PROJECT_ERROR_STUBS } from './AuthStatusLayer.constants';

import styles from './styles.module.css';

/**
 * Лоадер и заглушка ошибки — только для авторизации mobile, у капчи и VK ID их нет.
 * Заглушка показывается, только если она есть у темы проекта (сейчас только dso)
 */
export const AuthStatusLayer = () => {
  const { authType, status } = useAuth();
  const { widgetTheme } = useWidget();

  const ProjectErrorStub = widgetTheme ? PROJECT_ERROR_STUBS[widgetTheme] : undefined;
  const isLoaderShown = status === 'pending';
  const isErrorStubShown = status === 'error' && Boolean(ProjectErrorStub);

  if (authType !== 'mobile' || (!isLoaderShown && !isErrorStubShown)) {
    return null;
  }

  return (
    <div className={styles.authStatusLayer}>
      {isLoaderShown && (
        <div className={styles.loader}>
          <Spinner size="l" />
        </div>
      )}

      {isErrorStubShown && ProjectErrorStub && <ProjectErrorStub />}
    </div>
  );
};
