import { widgetEnableVkIdAutologin } from '../../../config';
import { isAuthType, type AuthType } from '../../auth/types';
import { DEFAULT_AUTH_TYPE } from '../../constants/auth';

/**
 * Способ авторизации из data-auth-type / ?auth-type=.
 * Без атрибута или с неизвестным значением — капча, чтобы не сломать уже встроенные виджеты.
 * VK ID работает только в сборках с VITE_ENABLE_VKID_AUTOLOGIN=true, иначе тоже капча
 */
export const resolveAuthType = (value?: string | null): AuthType => {
  if (!isAuthType(value)) {
    return DEFAULT_AUTH_TYPE;
  }

  if (value === 'vkid' && widgetEnableVkIdAutologin !== 'true') {
    return DEFAULT_AUTH_TYPE;
  }

  return value;
};
