/** Код ошибки из тела ответа бэкенда ({ code: string }), если он есть */
export const getResponseErrorCode = async (response: Response) => {
  try {
    const body = await response.json();

    return typeof body?.code === 'string' ? (body.code as string) : undefined;
  } catch (_) {
    return undefined;
  }
};
