import { getTracerModules } from '@apptracer/sdk/lite';

import { requestAccessToken } from '../../../utils/requestAccessToken';
import { sleep } from '../../../utils/sleep';
import { tokenManager } from '../../../utils/tokenManager';
import { withJitter } from '../../../utils/withJitter';

import { packageName } from '../../../../config';
import { getMobileAuthApi } from '../../../api/getMobileAuthApi';
import {
  MAX_RETRY_AFTER_SEC,
  PROVIDER_WAIT_MS,
  REFRESH_BEFORE_EXPIRE_SEC,
  RETRY_DELAYS_MS,
  RETRY_JITTER,
  USER_RETRY_COOLDOWN_MS,
} from '../../../constants/auth';
import { mobileAuthBridge } from '../../mobileAuthBridge';
import type { AuthError, AuthStrategy, AuthStrategyHost } from '../../types';

/**
 * Авторизация токеном внешнего проекта (data-auth-type="mobile"), подробно — docs/auth.md.
 * Токен проекта не храним: берём у провайдера в начале каждого обмена на JWT виджета.
 * Внутри одного обмена повторы идут с тем же токеном, новый запрашиваем только при 401 или ошибке провайдера
 */
export const createMobileStrategy = (host: AuthStrategyHost): AuthStrategy => {
  const tracerError = getTracerModules(packageName).error;

  // Поколение запросов: после dispose/logout результаты старых запросов игнорируются
  let generation = 0;
  // Текущий обмен: повторные вызовы authorize ждут его, а не запускают новый
  let inFlight: Promise<void> | null = null;
  // Фоновое обновление не удалось: не повторяем до истечения токена, чтобы не дёргать бэкенд
  let refreshError: AuthError | null = null;
  // Время последней неудачи: повтор по действию пользователя не раньше USER_RETRY_COOLDOWN_MS
  let lastFailedAt = 0;

  /** Пишет ошибку в трейсер и показывает заглушку. При фоновом обновлении живой токен не трогаем */
  const fail = (error: AuthError, isBackground: boolean) => {
    lastFailedAt = Date.now();

    tracerError?.error('Ошибка внешней авторизации', {
      keys: {
        code: error.code,
        status: error.status ?? '',
        widgetUuid: host.widgetUuid ?? '',
      },
    });

    // Токен ещё живой: пользователь продолжает работать, заглушку покажет onTick, когда токен истечёт
    if (isBackground && !tokenManager.getIsTokenExpired()) {
      refreshError = error;
      return;
    }

    host.setStatus('error', error);
  };

  /**
   * Один цикл обмена токена проекта на JWT виджета с повторами.
   * Шаги: дождаться провайдера → взять токен проекта → POST /auth/mobile → при ошибке повторить или показать заглушку
   */
  const exchange = async (currentGeneration: number, isBackground: boolean) => {
    // После dispose/logout цикл молча завершается, не меняя статус
    const getIsActual = () => currentGeneration === generation;
    const { widgetUuid } = host;

    if (!widgetUuid) {
      fail({ code: 'FORBIDDEN', retryable: false }, isBackground);
      return;
    }

    const provider = await mobileAuthBridge.waitForProvider(PROVIDER_WAIT_MS);

    if (!getIsActual()) return;

    if (!provider) {
      fail({ code: 'NO_TOKEN', retryable: false }, isBackground);
      return;
    }

    // Токен проекта для текущего цикла. null — нужно взять у провайдера (первая попытка или после 401)
    let accessToken: string | null = null;
    let isInvalidTokenRetried = false;
    let isRateLimitRetried = false;
    let retryAttempt = 0;

    /** Решает, повторять ли после ошибки. Если да — выдерживает паузу и возвращает true */
    const shouldRetry = async (error: AuthError) => {
      // Токен мог протухнуть между вызовом провайдера и обменом: один раз берём свежий
      if (error.code === 'INVALID_TOKEN' && !isInvalidTokenRetried) {
        isInvalidTokenRetried = true;
        accessToken = null;
        return true;
      }

      // 429: один повтор, только если бэкенд сам сказал, когда можно, и это недолго
      if (
        error.code === 'RATE_LIMIT' &&
        !isRateLimitRetried &&
        error.retryAfterSec !== undefined &&
        error.retryAfterSec <= MAX_RETRY_AFTER_SEC
      ) {
        isRateLimitRetried = true;
        await sleep(error.retryAfterSec * 1000);
        return true;
      }

      // Временные ошибки (5xx, сеть, провайдер): несколько повторов с растущей паузой
      if (error.retryable && retryAttempt < RETRY_DELAYS_MS.length) {
        await sleep(withJitter(RETRY_DELAYS_MS[retryAttempt], RETRY_JITTER));
        retryAttempt += 1;
        return true;
      }

      return false;
    };

    while (getIsActual()) {
      if (accessToken === null) {
        // Лимит вызовов провайдера общий для всех циклов: если исчерпан, ждём свободный слот
        const providerCallDelay = mobileAuthBridge.getProviderCallDelay();

        if (providerCallDelay > 0) {
          await sleep(providerCallDelay);
          if (!getIsActual()) return;
        }

        mobileAuthBridge.registerProviderCall();
        const tokenResult = await requestAccessToken(provider);

        if (!getIsActual()) return;

        if ('error' in tokenResult) {
          if (await shouldRetry(tokenResult.error)) continue;

          fail(tokenResult.error, isBackground);
          return;
        }

        accessToken = tokenResult.accessToken;
      }

      const result = await getMobileAuthApi(widgetUuid, accessToken);

      if (!getIsActual()) return;

      if (result.ok) {
        refreshError = null;
        // Статус authorized выставит authService по подписке на tokenManager
        tokenManager.setAuthData({ token: result.token, userUuid: result.userUuid });
        return;
      }

      if (await shouldRetry(result.error)) continue;

      fail(result.error, isBackground);
      return;
    }
  };

  /** Запускает цикл обмена, если он ещё не идёт. Фоновый цикл не показывает лоадер */
  const authorize = (isBackground = false) => {
    if (inFlight) return inFlight;

    if (!isBackground) {
      host.setStatus('pending');
    }

    const currentGeneration = generation;

    inFlight = exchange(currentGeneration, isBackground).finally(() => {
      if (currentGeneration === generation) {
        inFlight = null;
      }
    });

    return inFlight;
  };

  return {
    prepare() {
      // Сохранённому JWT не доверяем: во внешнем проекте мог смениться пользователь
      tokenManager.clearAllAuthAndKeys();
    },

    // Авторизуемся сразу при монтировании, не дожидаясь действия пользователя
    init() {
      void authorize();
    },

    // Действие пользователя без токена: новый цикл, но не чаще USER_RETRY_COOLDOWN_MS после неудачи
    requestAuth() {
      const status = host.getStatus();

      if (inFlight || status === 'pending') {
        return;
      }

      if (status === 'authorized' && !tokenManager.getIsTokenExpired()) {
        return;
      }

      if (Date.now() - lastFailedAt < USER_RETRY_COOLDOWN_MS) {
        return;
      }

      refreshError = null;
      void authorize();
    },

    // Заранее обновляем JWT, а если фоновое обновление не удалось — показываем заглушку, когда токен истечёт
    onTick() {
      if (inFlight) return;

      const expiresIn = tokenManager.getTokenExpiresIn();

      if (expiresIn === null || expiresIn > REFRESH_BEFORE_EXPIRE_SEC) {
        return;
      }

      if (!refreshError) {
        void authorize(true);
        return;
      }

      if (expiresIn <= 0) {
        const error = refreshError;
        refreshError = null;
        tokenManager.removeAuthData();
        host.setStatus('error', error);
      }
    },

    dispose() {
      generation += 1;
      inFlight = null;
      refreshError = null;
    },
  };
};
