/**
 * Вызывает fn и ждёт результат не дольше timeoutMs.
 * Отклоняется, если fn выбросила ошибку или не успела
 */
export const withTimeout = <T>(fn: () => T | Promise<T>, timeoutMs: number): Promise<T> => {
  let timerId: ReturnType<typeof setTimeout> | undefined;

  const timeout = new Promise<never>((_, reject) => {
    timerId = setTimeout(() => reject(new Error(`Превышено время ожидания ${timeoutMs} мс`)), timeoutMs);
  });

  return Promise.race([Promise.resolve().then(fn), timeout]).finally(() => clearTimeout(timerId));
};
