import type { TokenManagerData } from '../types/token-manager';
import { getAuthErrorByStatus } from '../utils/getAuthErrorByStatus';
import { getResponseErrorCode } from '../utils/getResponseErrorCode';
import { getRetryAfterSec } from '../utils/getRetryAfterSec';

import { widgetApi } from '../../config';
import type { MobileAuthResult } from '../auth/types';

/**
 * Обмен токена внешнего проекта на JWT виджета.
 * Не выбрасывает: любая неудача возвращается как AuthError, решение о повторе принимает createMobileStrategy
 */
export const getMobileAuthApi = async (widgetUuid: string, accessToken: string): Promise<MobileAuthResult> => {
  let response: Response;

  try {
    response = await fetch(`${widgetApi}/auth/mobile`, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
      },
      body: JSON.stringify({ accessToken, widgetUuid }),
    });
  } catch (_) {
    return { ok: false, error: { code: 'NETWORK_ERROR', retryable: true } };
  }

  if (!response.ok) {
    const error = getAuthErrorByStatus({
      status: response.status,
      backendCode: await getResponseErrorCode(response),
      retryAfterSec: getRetryAfterSec(response),
    });

    return { ok: false, error };
  }

  try {
    const data: TokenManagerData = await response.json();

    if (data?.token && data?.userUuid) {
      return { ok: true, token: data.token, userUuid: data.userUuid };
    }
  } catch (_) {
    // Невалидный JSON обрабатываем так же, как ответ без токена
  }

  return { ok: false, error: { code: 'SERVER_ERROR', status: response.status, retryable: true } };
};
