import { CommonErrorReasons } from './errors.js';
import { isRequiredHandler, isStringHandler, isFunctionHandler } from '../validator/validationRuleHandlers.js';
import { Validator } from '../validator/validator.js';

const bridgeConfigValidator = new Validator({
    iframe: [
        {
            rule: isRequiredHandler,
            errorText: CommonErrorReasons.validationIsRequired('iframe')
        }
    ],
    origin: [
        {
            rule: isStringHandler,
            errorText: CommonErrorReasons.validationIsString('origin')
        },
        {
            rule: isRequiredHandler,
            errorText: CommonErrorReasons.validationIsRequired('origin')
        }
    ]
});
const messageEventValidator = new Validator({
    event: [
        {
            rule: isRequiredHandler,
            errorText: CommonErrorReasons.validationIsRequired('event')
        }
    ]
});
const bridgeHandlerValidator = new Validator({
    handler: [
        {
            rule: isRequiredHandler,
            errorText: CommonErrorReasons.validationIsRequired('handler')
        },
        {
            rule: isFunctionHandler,
            errorText: CommonErrorReasons.validationIsFunction('handler')
        }
    ]
});
const messageDataRequirementValidator = new Validator({
    handler: [
        {
            rule: isRequiredHandler,
            errorText: CommonErrorReasons.validationIsRequired('handler')
        }
    ],
    params: [
        {
            rule: isRequiredHandler,
            errorText: CommonErrorReasons.validationIsRequired('params')
        }
    ]
});

export { bridgeConfigValidator, bridgeHandlerValidator, messageDataRequirementValidator, messageEventValidator };
