import { isWidgetCssInlined, widgetCssText } from '../../styles/widgetCss';

/**
 * Базовые стили хост-элемента: сбрасываем наследуемые стили хост-страницы,
 * которые проникают в Shadow DOM через наследование (font, color и т.п.).
 * Кастомные свойства (CSS variables) при этом продолжают наследоваться — `all` их не трогает.
 */
const HOST_RESET_CSS = `
:host {
  all: initial;
  display: block;
  font-family: var(--vkui--font_family_base, -apple-system, system-ui, 'Helvetica Neue', Roboto, sans-serif);
}
`;

const FONT_FACE_REGEX = /@font-face\s*\{[^}]*\}/g;

export interface WidgetShadowRoot {
  shadowRoot: ShadowRoot;
  /** Контейнер для порталов VKUI (popover, modal, tooltip и т.д.) — передаётся в AppRoot */
  portalRoot: HTMLDivElement;
}

/**
 * @font-face внутри Shadow DOM не поддерживается частью браузеров,
 * а регистрация шрифтов всё равно глобальная — выносим их в <head> хост-страницы.
 * Это не пробивает изоляцию: @font-face только регистрирует шрифт, ничего не стилизуя.
 */
const injectFontFacesIntoDocument = (css: string): void => {
  const fontFaces = css.match(FONT_FACE_REGEX);

  if (!fontFaces || fontFaces.length === 0) {
    return;
  }

  const style = document.createElement('style');
  style.setAttribute('data-vks-widget-fonts', '');
  style.textContent = fontFaces.join('\n');
  document.head.appendChild(style);
};

/**
 * Подготавливает Shadow Root на хост-элементе виджета:
 * подключает в него все стили виджета (VKUI + темы + CSS-модули) и создаёт контейнер для порталов.
 * preact-island сам обнаружит shadowRoot на элементе и отрендерит виджет внутрь.
 */
export const prepareWidgetShadowRoot = (hostElement: HTMLElement): WidgetShadowRoot => {
  const shadowRoot = hostElement.shadowRoot ?? hostElement.attachShadow({ mode: 'open' });

  if (isWidgetCssInlined && !shadowRoot.querySelector('style[data-vks-widget-styles]')) {
    injectFontFacesIntoDocument(widgetCssText);

    const style = document.createElement('style');
    style.setAttribute('data-vks-widget-styles', '');
    style.textContent = HOST_RESET_CSS + widgetCssText;
    shadowRoot.prepend(style);
  }

  let portalRoot = shadowRoot.querySelector<HTMLDivElement>('[data-vks-portal-root]');

  if (!portalRoot) {
    portalRoot = document.createElement('div');
    portalRoot.setAttribute('data-vks-portal-root', '');
    shadowRoot.appendChild(portalRoot);
  }

  return { shadowRoot, portalRoot };
};
