.header {
  position: relative;
  z-index: 1000;
  background: var(--vkui--color_background_content);
}

.closeButton {
  cursor: pointer;
}

.header .closeButton:global(.vkuiIcon) {
  color: var(--header-close-icon-color, var(--vkui--color_icon_secondary));
}

.title {
  font-family: var(--heading-font-family, inherit);
  font-size: var(--header-title-font-size, inherit);
  font-weight: var(--heading-font-weight, inherit);
  line-height: var(--header-title-line-height, inherit);
}

.header + .separator {
  display: var(--header-separator-display, flex);
}
