import { querystring } from '../lib/@vkontakte/vkjs/lib/es6/querystring.js';
import Base64 from 'crypto-js/enc-base64';
import sha256 from 'crypto-js/sha256';
import { nanoid } from '../lib/nanoid/non-secure/index.js';
import { ALLOWED_APP_SETTINGS_KEYS } from './constants.js';

function makeParams(params) {
    return querystring.stringify(params, {
        skipNull: true
    });
}
function filterAllowedAppSettingsKeys(appSettings) {
    return Object.keys(appSettings).filter((settingsKey)=>ALLOWED_APP_SETTINGS_KEYS.includes(settingsKey));
}
function hasAllowedAppSettingsParams(appSettings) {
    return Boolean(filterAllowedAppSettingsKeys(appSettings)?.length);
}
function filterAllowedAppSettings(appSettings) {
    const filteredSettingsKeys = filterAllowedAppSettingsKeys(appSettings);
    return filteredSettingsKeys.reduce((appSettingsObj, settingsKey)=>{
        /**
     * TS2322: Type 'string | Record<string, string> | undefined' is not assignable to type '(string & Record<string, string>) | undefined'.
     * Type 'string' is not assignable to type '(string & Record<string, string>) | undefined'.
     */ //  @ts-ignore
        appSettingsObj[settingsKey] = appSettings[settingsKey];
        return appSettingsObj;
    }, {});
}
function makeAppSettingsString(appSettings) {
    const appSettingsFiltered = filterAllowedAppSettings(appSettings);
    return btoa(JSON.stringify(appSettingsFiltered));
}
function makeFrame(src, frameSettings) {
    const iframe = document.createElement('iframe');
    if (src) {
        iframe.src = src;
    }
    iframe.style.cssText = frameSettings?.cssText ?? '';
    // Общие стили по-умолчанию, переопределяются по необходимости
    iframe.width = '100%';
    iframe.height = '100%';
    iframe.style.border = 'none';
    iframe.style.colorScheme = 'none';
    for(let key in frameSettings?.properties){
        if (frameSettings && frameSettings.properties.hasOwnProperty(key)) {
            iframe[key] = frameSettings.properties[key] ?? '';
        }
    }
    return iframe;
}
function getScrollbarSize() {
    // A change of the browser zoom change the scrollbar size.
    // Credit https://github.com/twbs/bootstrap/blob/488fd8afc535ca3a6ad4dc581f5e89217b6a36ac/js/src/util/scrollbar.js#L14-L18
    // https://developer.mozilla.org/en-US/docs/Web/API/Window/innerWidth#usage_notes
    const documentWidth = window.document.documentElement.clientWidth;
    return Math.abs(window.innerWidth - documentWidth);
}
function mergeDeep(...objects) {
    const isObject = (obj)=>obj && typeof obj === 'object';
    return objects.reduce((prev, obj)=>{
        Object.keys(obj).forEach((key)=>{
            const pVal = prev[key];
            const oVal = obj[key];
            if (Array.isArray(pVal) && Array.isArray(oVal)) {
                prev[key] = pVal.concat(...oVal);
            } else if (isObject(pVal) && isObject(oVal)) {
                prev[key] = mergeDeep(pVal, oVal);
            } else {
                prev[key] = oVal;
            }
        });
        return prev;
    }, {});
}
/**
 Фильтрация свойств объекта на верхнем уровне, без вложенных свойств
 */ function filterObjectKeys(obj, filterKeys) {
    if (!obj || typeof obj !== 'object') {
        return obj;
    }
    // const keys = Object.keys(obj).filter((key) => filterKeys.includes(key));
    return Object.keys(obj).reduce((filteredObj, key)=>{
        if (!filterKeys.includes(key)) {
            return filteredObj;
        }
        filteredObj[key] = obj[key];
        return filteredObj;
    }, {});
}
/**
 Генерация code_challenge для нового oauth
 */ const generateCodeChallenge = (codeVerifier)=>{
    const hash = sha256(codeVerifier);
    const base64 = Base64.stringify(hash);
    return base64.replace(/=*$/g, '').replace(/\+/g, '-').replace(/\//g, '_');
};
const generateCodeVerifier = ()=>nanoid().replace('-', '').replace('_', '');

export { filterAllowedAppSettings, filterObjectKeys, generateCodeChallenge, generateCodeVerifier, getScrollbarSize, hasAllowedAppSettingsParams, makeAppSettingsString, makeFrame, makeParams, mergeDeep };
