/**
 * В продакшен embed-сборке плейсхолдер заменяется на весь CSS бандла строкой,
 * а __VKS_WIDGET_CSS_INLINED__ подставляется как true через define
 * (см. плагин inlineCssIntoWidgetJs и define в vite.config.embed.ts).
 * В dev-режиме и тестах стили подключаются обычным способом, поэтому здесь false.
 *
 * Флаг отдельный, а не сравнение widgetCssText с плейсхолдером: минификатор
 * вычисляет такое сравнение на этапе сборки и выкидывает код инъекции стилей.
 */
export const widgetCssText = '__VKS_CHAT_WIDGET_CSS__';

export const isWidgetCssInlined: boolean =
  typeof __VKS_WIDGET_CSS_INLINED__ !== 'undefined' && __VKS_WIDGET_CSS_INLINED__;
