import { nanoid } from '../lib/nanoid/non-secure/index.js';
import { AuthByAutologinCallbackErrorEventsSDK } from './events.js';
import { isAutologinRetryAvailable, setAutologinTimestamp, makeAutologinUrl, notificationText } from './utils.js';
import { redirectAuthValidator } from '../connect/validators.js';
import { Notification } from '../notification/notification.js';
import { NotificationEvents } from '../notification/events.js';
import { NotificationColorScheme } from '../notification/types.js';

// eslint-disable-next-line @typescript-eslint/no-extraneous-class
class Autologin {
    static autologinRedirect = ({ autologin_delay = 24, ...params })=>{
        const validationResult = redirectAuthValidator.validate(params);
        !validationResult.isValid() && console.error(validationResult.error());
        const uuid = nanoid();
        if (!isAutologinRetryAvailable(autologin_delay)) {
            if (!!params.callback) {
                params.callback(AuthByAutologinCallbackErrorEventsSDK.RETRY_COOL_DOWN);
            }
            return;
        }
        const urlParams = {
            redirect_uri: params.url,
            uuid,
            state: params.state
        };
        setAutologinTimestamp();
        void makeAutologinUrl(urlParams).then((url)=>{
            location.assign(url);
        });
    };
    static showNotification = async ({ userName, avatar, agreementLink, langId = 0 })=>{
        const translation = notificationText(langId);
        const notification = new Notification({
            notificationText: translation.loggedWithUser(userName),
            vkIdBlockText: translation.signedInVkId,
            beforeImageUrl: avatar,
            actionButtonText: translation.agreementText,
            scheme: NotificationColorScheme.DARK
        });
        if (agreementLink) {
            notification.on(NotificationEvents.ACTION_BUTTON_CLICK, ()=>{
                window.open(agreementLink);
            });
            await notification.open();
        }
    };
}

export { Autologin };
