import mitt from '../lib/mitt/dist/mitt.es.js';
import Bridge from '../common/bridge.js';
import { CommonErrorReasons, ERROR_CODES } from '../common/errors.js';
import { CommonSDKEvents, CommonInternalSDKEvents } from '../common/events.js';
import PendingTask from '../common/pendingTask.js';
import { makeFrame, makeParams, mergeDeep } from '../common/utils.js';
import { Config } from '../config/config.js';
import { ConfigInternalEvents } from '../config/events.js';
import { makeLegacyError, makeError } from '../errors/errors.js';
import { messageRequirementValidator, onOffValidator } from '../validator/validators.js';
import { paramsValidator } from './validators.js';

class BaseModule {
    config = {};
    params = {};
    bridge;
    iframe;
    loadingTask = new PendingTask();
    initTask = new PendingTask();
    timeoutTimer;
    cssText = '';
    moduleInitTimeoutMs = 5000;
    events;
    constructor(){
        this.events = mitt();
        this.handleBridgeMessage = this.handleBridgeMessage.bind(this);
        this.handleChangeSuperAppToken = this.handleChangeSuperAppToken.bind(this);
        this.close = this.close.bind(this);
        this.handleLogout = this.handleLogout.bind(this);
    }
    // <Публичные методы модуля>
    /**
   * Предзагрузка модуля. Будет создан скрытый айфрейм.
   */ preload(params) {
        return Config.fetchDomain().then(()=>{
            return this.validateParams(params).then(()=>{
                this.updateParams(params);
                return this.createIframe().then(()=>{
                    this.initTask.start();
                    this.loadingTask.start();
                    this.timeoutTimer = setTimeout(()=>{
                        if (this.initTask.finished) {
                            return;
                        }
                        const error = makeLegacyError(makeError(ERROR_CODES[ERROR_CODES.LOADING_ERROR], ERROR_CODES.LOADING_ERROR, CommonErrorReasons.loadingTimeout()));
                        this.initTask.reject(error);
                    }, this.moduleInitTimeoutMs);
                    this.iframe.onload = ()=>{
                        this.iframe.onload = null;
                        this.loadingTask.resolve();
                    };
                    this.bridge = new Bridge({
                        iframe: this.iframe,
                        origin: 'https://' + Config.get().connectDomain
                    });
                    // eslint-disable-next-line
                    this.bridge.onMessage(this.handleBridgeMessage);
                    // eslint-disable-next-line
                    Config.events.on(ConfigInternalEvents.SUPERAPP_TOKEN_CHANGE_V2, this.handleChangeSuperAppToken);
                    // eslint-disable-next-line
                    Config.events.on(CommonSDKEvents.LOGOUT, this.close);
                    this.getIframeContainer().appendChild(this.iframe);
                    return this.loadingTask.get();
                });
            });
        });
    }
    /**
   * Метод показывает модуль. Автоматически вызовет preload, если это не было сделано в ручную.
   */ open(params) {
        return this.validateParams(params).then(()=>{
            if (this.initTask.finished) {
                this.updateParams(params);
                return Promise.resolve();
            }
            if (!this.initTask.active && !this.initTask.finished) {
                return this.preload(params).then(()=>this.initTask.get());
            }
            this.updateParams(params);
            return this.initTask.get();
        });
    }
    /**
   * Обновление настроек модуля.
   */ update(params, config) {
        if (params) {
            this.updateParams(params);
        }
        if (config) {
            this.updateConfig(config);
        }
    }
    /**
   * Метод закрывает модуль, так же он будет удален со страницы.
   */ close() {
        if (this.iframe) {
            this.iframe.onload = null;
            this.iframe.remove();
        }
        this.bridge && this.bridge.destroy();
        // eslint-disable-next-line
        Config.events.off(ConfigInternalEvents.SUPERAPP_TOKEN_CHANGE_V2, this.handleChangeSuperAppToken);
        // eslint-disable-next-line
        Config.events.off(CommonSDKEvents.LOGOUT, this.close);
        /* Clear references for memory */ // @ts-ignore-next-line Деструктуризация объекта.
        delete this.iframe;
        // @ts-ignore-next-line Деструктуризация объекта.
        delete this.bridge;
        this.loadingTask = new PendingTask();
        this.initTask = new PendingTask();
        this.events.emit(CommonSDKEvents.CLOSE);
    }
    /**
   * Метод отправляет сообщение в айфрейм.
   */ sendMessage(message) {
        const validationResult = messageRequirementValidator.validate({
            message
        });
        !validationResult.isValid() && console.error(validationResult.error());
        this.bridge.sendMessage(message);
    }
    /**
   * Метод добавляет подписку на событие модуля.
   */ on(event, handler) {
        const validationResult = onOffValidator.validate({
            event,
            handler
        });
        !validationResult.isValid() && console.error(validationResult.error());
        this.events.on(event, handler);
    }
    /**
   * Метод удаляет подписку на событие модуля.
   */ off(event, handler) {
        const validationResult = onOffValidator.validate({
            event,
            handler
        });
        !validationResult.isValid() && console.error(validationResult.error());
        this.events.off(event, handler);
    }
    // </Публичные методы модуля>
    // <Базовые методы жизненного цикла модуля>
    handleInit() {
        if (!this.initTask.finished) {
            clearTimeout(this.timeoutTimer);
            this.initTask.resolve();
        }
        this.sendUpdateParamsMessage();
        this.iframe.style.display = 'block';
    }
    /** Метод вызывается при запросе авторизации со стороны айфрейма */ handleRequestAuth() {
        Config._auth({
            version: 2
        });
    }
    /** Метод вызывается при запросе superapp token со стороны айфрейма */ handleRequestSuperAppToken(params) {
        Config._requestSuperAppToken(params, {
            version: 2
        });
    }
    /** Метод вызывается при изменении superapp token в конфиге */ handleChangeSuperAppToken(token) {
        this.bridge.sendMessage({
            handler: `${CommonSDKEvents.REQUEST_SUPERAPP_TOKEN}Success`,
            params: {
                result: token
            }
        });
    }
    /** Метод вызывается при событии ошибки со стороны айфрейма */ handleError = (data)=>{
        const error = makeLegacyError(makeError(ERROR_CODES[ERROR_CODES.CUSTOM], ERROR_CODES.CUSTOM, '', data));
        this.events.emit(CommonSDKEvents.ERROR, error);
    };
    /** Метод вызывается при событии со стороны айфрейма */ handleBridgeMessage(data) {
        switch(data.handler){
            case CommonInternalSDKEvents.INIT:
                this.handleInit();
                break;
            case CommonSDKEvents.REQUEST_SUPERAPP_TOKEN:
                this.handleRequestSuperAppToken(data.params);
                break;
            case CommonSDKEvents.AUTH_NEEDED:
                this.handleRequestAuth();
                break;
            case CommonSDKEvents.CLOSE:
                this.close();
                break;
            case CommonSDKEvents.ERROR:
                {
                    this.handleError(data.params);
                    break;
                }
            default:
                return;
        }
    }
    /** Метод для вызова logout */ handleLogout() {
        Config._logout();
    }
    /** Метод вызывается после обновления параметров модуля */ handleAfterUpdateParams() {
        this.sendUpdateParamsMessage();
    }
    /** Метод вызывается после обновления конфига модуля */ handleAfterUpdateConfig() {
    // Will be implemented in a subclass.
    }
    /** Метод вызывается после создания айфрейма */ handleAfterCreateIframe() {
    // Will be implemented in a subclass.
    }
    // </Базовые методы жизненного цикла модуля>
    // <Дополнительные хелперы>
    validateParams(params) {
        const validationResult = paramsValidator.validate({
            params
        });
        !validationResult.isValid() && console.error(validationResult.error());
        return Promise.resolve(params);
    }
    createIframe() {
        return this.getIframeUrl().then((src)=>{
            this.iframe = makeFrame(src, {
                cssText: this.cssText
            });
            this.handleAfterCreateIframe();
            return Promise.resolve();
        });
    }
    getIframeUrl() {
        return new Promise((resolve)=>{
            return resolve('');
        });
    }
    getIframeContainer() {
        return window.document.body;
    }
    getIframeUrlParams() {
        return Config.fetchDomain().then(()=>{
            const { superAppTokenV2, appId, _debug, _localhost } = Config.get();
            return Promise.resolve(makeParams({
                ...this.params,
                host_app_id: appId,
                superapp_token: superAppTokenV2,
                origin: location.protocol + '//' + location.host,
                debug: _debug ? 1 : null,
                localhost: _localhost ? 1 : null
            }));
        });
    }
    updateConfig(config) {
        this.config = mergeDeep(this.config, config);
        this.handleAfterUpdateConfig();
    }
    updateParams(params) {
        this.params = mergeDeep(this.params, params || {});
        this.handleAfterUpdateParams();
    }
    sendUpdateParamsMessage() {
        if (!this.bridge || !this.initTask.finished) {
            return;
        }
        this.bridge.sendMessage({
            params: this.params,
            handler: CommonSDKEvents.UPDATE_PARAMS
        });
    }
}

export { BaseModule };
