import { PROVIDER_CALLS_LIMIT, PROVIDER_CALLS_WINDOW_MS } from '../../constants/auth';
import type { AuthTokenProvider } from '../types';

type ProviderWaiter = (provider: AuthTokenProvider) => void;

/**
 * Связь виджета с внешним проектом при авторизации mobile.
 * Провайдер можно передать и до монтирования виджета, поэтому он хранится здесь, а не в React
 */
class MobileAuthBridge {
  private provider: AuthTokenProvider | null = null;
  private waiters = new Set<ProviderWaiter>();
  // Время последних вызовов провайдера. Общее для всех сессий: logout не сбрасывает лимит
  private providerCalls: number[] = [];

  setProvider(provider: AuthTokenProvider | null | undefined) {
    this.provider = typeof provider === 'function' ? provider : null;

    if (this.provider) {
      const current = this.provider;
      this.waiters.forEach((waiter) => waiter(current));
      this.waiters.clear();
    }
  }

  /** Через сколько мс можно вызвать провайдер, не превысив лимит. 0 — можно сейчас */
  getProviderCallDelay() {
    const now = Date.now();
    this.providerCalls = this.providerCalls.filter((time) => now - time < PROVIDER_CALLS_WINDOW_MS);

    if (this.providerCalls.length < PROVIDER_CALLS_LIMIT) {
      return 0;
    }

    return this.providerCalls[0] + PROVIDER_CALLS_WINDOW_MS - now;
  }

  registerProviderCall() {
    this.providerCalls.push(Date.now());
  }

  /** Ждёт провайдер не дольше timeoutMs, иначе возвращает null */
  waitForProvider(timeoutMs: number): Promise<AuthTokenProvider | null> {
    if (this.provider) {
      return Promise.resolve(this.provider);
    }

    return new Promise((resolve) => {
      const waiter: ProviderWaiter = (provider) => {
        clearTimeout(timerId);
        resolve(provider);
      };

      const timerId = setTimeout(() => {
        this.waiters.delete(waiter);
        resolve(null);
      }, timeoutMs);

      this.waiters.add(waiter);
    });
  }
}

export const mobileAuthBridge = new MobileAuthBridge();
