import { Icon24AddCircle, Icon24AddCircleOutline } from '@vkontakte/icons';
import { Button } from '@vkontakte/vkui';
import baseTheme from '@vkontakte/vkui-tokens/themes/vkBase';

import { useWidget } from '../../context/WidgetContext';

import styles from './styles.module.css';

interface Props {
  onClick: () => void;
}

export const AttachFilesButton = ({ onClick }: Props) => {
  const { widgetTheme } = useWidget();

  const icon =
    widgetTheme === 'dso' ? (
      <Icon24AddCircle className={styles.dsoIcon} width={32} height={32} fill="currentColor" />
    ) : (
      <Icon24AddCircleOutline fill={baseTheme.colorIconSecondary.normal} />
    );

  return <Button mode="tertiary" before={icon} onClick={onClick} />;
};
