import { useEffect } from 'preact/hooks';

import { useWidget } from '../context/WidgetContext';
import { isRateLimitError } from '../types/guards';
import type { TokenManagerData } from '../types/token-manager';
import { setBooleanToStorage, tokenManager } from '../utils';

import { getHasMaxUserPhone } from '../api/getHasMaxUserPhone';
import { HAS_MAX_USER_PHONE } from '../constants/localStorage';

/**
 * После получения нового токена (капча, VK ID, внешняя авторизация)
 * проверяет наличие телефона пользователя, если проект требует телефон
 */
export const usePhoneCheckAfterAuth = () => {
  const { requirePhone, setHasMaxUserPhone, setError, localeMessages } = useWidget();

  useEffect(() => {
    if (!requirePhone) {
      return;
    }

    let isActive = true;

    const callback = async (data?: TokenManagerData) => {
      if (!data?.token) {
        return;
      }

      try {
        const { hasMaxUserPhone } = await getHasMaxUserPhone(data.token);

        if (!isActive) return;

        setHasMaxUserPhone?.(hasMaxUserPhone);
        // Сохраняем в localStorage для восстановления при перезагрузке
        setBooleanToStorage(HAS_MAX_USER_PHONE, hasMaxUserPhone);
      } catch (error: unknown) {
        if (isActive && isRateLimitError(error)) {
          setError?.(localeMessages.errors.rateLimit);
        }
      }
    };

    tokenManager.subscribe(callback);

    return () => {
      isActive = false;
      tokenManager.unsubscribe(callback);
    };
  }, [requirePhone, setHasMaxUserPhone, setError, localeMessages]);
};
