import type { AuthError } from '../../auth/types';
import {
  HTTP_STATUS_FORBIDDEN,
  HTTP_STATUS_INTERNAL_SERVER_ERROR,
  HTTP_STATUS_REQUEST_TIMEOUT,
  HTTP_STATUS_TOO_MANY_REQUESTS,
  HTTP_STATUS_UNAUTHORIZED,
} from '../../constants/api';

interface Params {
  status: number;
  /** Код ошибки из тела ответа, пишется в трейсер */
  backendCode?: string;
  retryAfterSec?: number;
}

/** Ошибка авторизации по HTTP-статусу неуспешного ответа бэкенда */
export const getAuthErrorByStatus = ({ status, backendCode, retryAfterSec }: Params): AuthError => {
  // Токен проекта не принят: можно взять у провайдера свежий
  if (status === HTTP_STATUS_UNAUTHORIZED) {
    return { code: 'INVALID_TOKEN', status, retryable: false, backendCode };
  }

  if (status === HTTP_STATUS_FORBIDDEN) {
    return { code: 'FORBIDDEN', status, retryable: false, backendCode };
  }

  // Сработал rate limit бэкенда: быстрые повторы только усилят нагрузку
  if (status === HTTP_STATUS_TOO_MANY_REQUESTS) {
    return { code: 'RATE_LIMIT', status, retryable: false, retryAfterSec, backendCode };
  }

  // 5xx и таймаут запроса имеет смысл повторить, остальные 4xx — нет
  const retryable = status >= HTTP_STATUS_INTERNAL_SERVER_ERROR || status === HTTP_STATUS_REQUEST_TIMEOUT;

  return { code: 'SERVER_ERROR', status, retryable, backendCode };
};
